<?php namespace Workspace; $states=['pending'=>'Ожидает','posted'=>'Проведена','rejected'=>'Отклонена','cancelled'=>'Отменена']; ?>
<p class="lede">Заявки, решения и связь с кассовой книгой. Ожидающие заявки не включаются в баланс.</p>
<form method="get" class="filters"><input type="hidden" name="p" value="payments"><label>Проект<select name="project"><option value="">Все доступные</option><?php selectOptions($projects,$selected) ?></select></label><button class="secondary">Применить</button></form>
<section class="panel"><div class="panelhead"><h2>Заявки</h2></div><?php if (!$payments): ?><p class="empty">Нет заявок.</p><?php else: ?><div class="tablewrap"><table><thead><tr><th>Заявка / проект</th><th>Сумма</th><th>Автор / дата</th><th>Решение</th><th>Действия</th></tr></thead><tbody>
<?php foreach ($payments as $r): ?><tr><td><b>#<?= h($r['id']) ?> · <?= h($r['project_title']) ?></b><small><?= h($r['memo']) ?></small><?php if ($r['reversal_of']!==null): ?><small>Сторно #<?= h($r['reversal_of']) ?></small><?php endif ?></td><td><?= h(DIRECTIONS[$r['direction']]) ?> <?= h(money((int)$r['amount_minor']).' '.$r['currency']) ?></td><td><?= h($r['creator']) ?><small><?= h($r['created_at']) ?> UTC · дата учёта <?= h($r['booked_on']) ?></small></td><td><?= h($states[$r['status']]) ?><?php if ($r['decider']!==null): ?><small><?= h($r['decider']) ?> · <?= h($r['decided_at']) ?> UTC</small><?php endif ?><?php if ($r['cash_entry_id']!==null): ?><small>Кассовая запись #<?= h($r['cash_entry_id']) ?></small><?php endif ?></td><td>
<?php if ($r['status']==='pending'): $own=(int)$r['created_by']===(int)$user['id']; $actions=[]; if (isset($approvable[$r['project_id']])) { if (!$own) $actions['approve']='Утвердить'; $actions['reject']='Отклонить'; } if ($own && isset($creatable[$r['project_id']])) $actions['cancel']='Отменить'; foreach ($actions as $act=>$label): ?><form method="post"><?php formFields('payment.'.$act) ?><input type="hidden" name="payment_id" value="<?= h($r['id']) ?>"><button class="secondary compact"><?= h($label) ?></button></form><?php endforeach; endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<?php if ($nextBefore): ?><div class="pager"><a href="<?= h(url('payments',array_filter(['project'=>$selected,'before'=>$nextBefore]))) ?>">Следующая страница</a></div><?php endif ?></section>
